use anyhow::{anyhow, Result};
use clap::Parser;
use prettytable::Table;
use regex::Regex;
use serde_json::{json, Map, Value};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(version = "1.6.4")]
#[command(about = "Batch rename utility for developers")]
#[command(long_about = "OUTPUT pattern accepts placeholders that have the format of '{G:P}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.")]
struct Args {
    /// OUTPUT is the pattern to be used for renaming files, and SOURCE is the optional regex pattern to match by filenames. SOURCE has the same function as -r option
    #[arg(value_name = "[SOURCE] OUTPUT")]
    patterns: Vec<String>,

    /// Sets the working directory
    #[arg(short, long, value_name = "PATH")]
    dir: Option<PathBuf>,

    /// Optional value to overwrite inferred subdirectory depth value in 'regex' mode
    #[arg(long, value_name = "DEPTH")]
    depth: Option<usize>,

    /// Does not preserve the extension of input files in 'sort' and 'regex' options
    #[arg(short = 'E', long)]
    no_extension: bool,

    /// Stores a JSON map file in '<PATH>' after renaming files
    #[arg(short, long, value_name = "PATH")]
    generate: Option<PathBuf>,

    /// Recursively creates all parent directories of '<OUTPUT>' if they are missing
    #[arg(short, long)]
    mkdir: bool,

    /// Sets the path of map file to be used for renaming files
    #[arg(short, long, value_name = "PATH", alias = "from-file")]
    map: Option<PathBuf>,

    /// Optional value to set the maximum of subdirectory depth value in 'regex' mode
    #[arg(long, value_name = "DEPTH")]
    max_depth: Option<usize>,

    /// Does not print the map table to stdout
    #[arg(short, long)]
    quiet: bool,

    /// Regex pattern to match by filenames
    #[arg(short, long, value_name = "PATTERN")]
    regex: Option<String>,

    /// Sets the order of natural sorting (by name) to rename files using enumerator
    #[arg(short, long, value_name = "ORDER")]
    sort: Option<String>,

    /// Runs in test mode without renaming actual files
    #[arg(short, long, alias = "dry-run")]
    test: bool,

    /// Overwrites output files, otherwise, a '_' is prepended to filename
    #[arg(short, long)]
    overwrite: bool,
}

struct RenameOperation {
    input: String,
    output: String,
}

fn main() -> Result<()> {
    let args = Args::parse();

    let work_dir = args.dir.unwrap_or_else(|| PathBuf::from("."));
    let work_dir = std::fs::canonicalize(&work_dir)
        .map_err(|e| anyhow!("Invalid directory '{}': {}", work_dir.display(), e))?;

    // If using a map file
    if let Some(map_path) = args.map {
        let map_content = fs::read_to_string(&map_path)
            .map_err(|e| anyhow!("Failed to read map file: {}", e))?;
        let map: Map<String, Value> = serde_json::from_str(&map_content)
            .map_err(|e| anyhow!("Invalid JSON in map file: {}", e))?;

        let mut operations = Vec::new();
        for (input, output) in map {
            let output_str = output
                .as_str()
                .ok_or_else(|| anyhow!("Map values must be strings"))?
                .to_string();
            operations.push(RenameOperation {
                input,
                output: output_str,
            });
        }

        apply_renames(&work_dir, &operations, args.test, args.overwrite, args.quiet)?;
        return Ok(());
    }

    // Parse patterns
    let (source_pattern, output_pattern) = if args.patterns.is_empty() {
        return Err(anyhow!("At least an output pattern is required"));
    } else if args.patterns.len() == 1 {
        (None, args.patterns[0].clone())
    } else {
        (Some(args.patterns[0].clone()), args.patterns[1].clone())
    };

    // Get files from directory
    let mut files = get_files(&work_dir)?;

    // Sort files if needed
    if let Some(sort_order) = &args.sort {
        files.sort_by(|a, b| {
            let cmp = alphanumeric_sort::compare_str(
                a.file_name().unwrap_or_default().to_string_lossy().as_ref(),
                b.file_name().unwrap_or_default().to_string_lossy().as_ref(),
            );
            match sort_order.as_str() {
                "asc" => cmp,
                "desc" => cmp.reverse(),
                _ => cmp,
            }
        });
    } else {
        // Natural alphabetical sort by default
        files.sort_by(|a, b| {
            let a_name = a.file_name().unwrap_or_default().to_string_lossy();
            let b_name = b.file_name().unwrap_or_default().to_string_lossy();
            a_name.cmp(&b_name)
        });
    }

    let mut operations = Vec::new();

    // Use regex pattern if provided (either from --regex or SOURCE)
    let regex_pattern = args.regex.as_ref().or(source_pattern.as_ref());

    if let Some(regex_str) = regex_pattern {
        let regex = Regex::new(regex_str)
            .map_err(|e| anyhow!("Invalid regex pattern: {}", e))?;

        for (idx, file_path) in files.iter().enumerate() {
            let file_name = file_path.file_name().unwrap_or_default().to_string_lossy();

            if regex.is_match(&file_name) {
                let output_name = apply_regex_replacement(
                    &file_name,
                    &regex,
                    &output_pattern,
                    args.no_extension,
                    file_path,
                )?;
                operations.push(RenameOperation {
                    input: file_name.to_string(),
                    output: output_name,
                });
            }
        }
    } else {
        // Sort mode: enumerate files
        for (idx, file_path) in files.iter().enumerate() {
            let file_name = file_path.file_name().unwrap_or_default().to_string_lossy();
            let (base, ext) = if args.no_extension {
                (file_name.to_string(), String::new())
            } else {
                split_filename(&file_name)
            };

            // Replace placeholders in output pattern
            let mut context = PlaceholderContext::new();
            context.set_filename(&base);
            context.set_auto_index(1, (idx + 1).to_string());

            let output_name = replace_placeholders(&output_pattern, &context);
            let final_output = if args.no_extension {
                output_name
            } else {
                format!("{}{}", output_name, ext)
            };

            operations.push(RenameOperation {
                input: file_name.to_string(),
                output: final_output,
            });
        }
    }

    apply_renames(&work_dir, &operations, args.test, args.overwrite, args.quiet)?;

    // Generate map file if requested
    if let Some(gen_path) = args.generate {
        let mut map = Map::new();
        for op in &operations {
            map.insert(op.output.clone(), Value::String(op.input.clone()));
        }
        let json = Value::Object(map);
        let json_str = serde_json::to_string_pretty(&json)
            .map_err(|e| anyhow!("Failed to serialize JSON: {}", e))?;
        fs::write(&gen_path, json_str)
            .map_err(|e| anyhow!("Failed to write generated map file: {}", e))?;
    }

    Ok(())
}

fn get_files(dir: &Path) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();
    for entry in fs::read_dir(dir)
        .map_err(|e| anyhow!("Failed to read directory: {}", e))?
    {
        let entry = entry.map_err(|e| anyhow!("Error reading directory entry: {}", e))?;
        let path = entry.path();
        if path.is_file() {
            files.push(path);
        }
    }
    Ok(files)
}

fn split_filename(filename: &str) -> (String, String) {
    if let Some(pos) = filename.rfind('.') {
        if pos > 0 {
            let base = filename[..pos].to_string();
            let ext = filename[pos..].to_string();
            return (base, ext);
        }
    }
    (filename.to_string(), String::new())
}

struct PlaceholderContext {
    captures: HashMap<String, String>,
    auto_counter: usize,
}

impl PlaceholderContext {
    fn new() -> Self {
        Self {
            captures: HashMap::new(),
            auto_counter: 0,
        }
    }

    fn set_filename(&mut self, name: &str) {
        self.captures.insert("0".to_string(), name.to_string());
    }

    fn set_capture(&mut self, idx: usize, value: String) {
        self.captures.insert(idx.to_string(), value);
    }

    fn set_auto_index(&mut self, idx: usize, value: String) {
        self.captures.insert(idx.to_string(), value);
    }

    fn get(&self, key: &str) -> Option<String> {
        self.captures.get(key).cloned()
    }
}

fn replace_placeholders(pattern: &str, ctx: &PlaceholderContext) -> String {
    let mut result = String::new();
    let mut chars = pattern.chars().peekable();
    let mut auto_index = 1;

    while let Some(ch) = chars.next() {
        if ch == '{' {
            let mut placeholder = String::new();
            let mut found_close = false;

            while let Some(&next_ch) = chars.peek() {
                let next_ch = chars.next().unwrap();
                if next_ch == '}' {
                    found_close = true;
                    break;
                }
                placeholder.push(next_ch);
            }

            if found_close {
                let parts: Vec<&str> = placeholder.split(':').collect();
                let group_str = parts[0];
                let padding = if parts.len() > 1 {
                    parts[1].parse::<usize>().unwrap_or(0)
                } else {
                    0
                };

                let value = if group_str.is_empty() {
                    // Auto increment
                    let val = ctx.get(&auto_index.to_string()).cloned().unwrap_or_default();
                    auto_index += 1;
                    val
                } else {
                    ctx.get(group_str).cloned().unwrap_or_default()
                };

                let formatted = format_value(&value, padding);
                result.push_str(&formatted);
            } else {
                result.push('{');
                result.push_str(&placeholder);
            }
        } else if ch == '\\' && chars.peek() == Some(&'{') {
            chars.next();
            result.push('{');
        } else if ch == '\\' && chars.peek() == Some(&'}') {
            chars.next();
            result.push('}');
        } else {
            result.push(ch);
        }
    }

    result
}

fn format_value(value: &str, padding: usize) -> String {
    if padding == 0 {
        return value.to_string();
    }

    // Try to parse as number
    if let Ok(num) = value.parse::<i64>() {
        if num >= 0 {
            format!("{:0width$}", num, width = padding)
        } else {
            value.to_string()
        }
    } else {
        value.to_string()
    }
}

fn apply_regex_replacement(
    filename: &str,
    regex: &Regex,
    output_pattern: &str,
    no_extension: bool,
    file_path: &Path,
) -> Result<String> {
    let (base, ext) = if no_extension {
        (filename.to_string(), String::new())
    } else {
        split_filename(filename)
    };

    if let Some(caps) = regex.captures(&base) {
        let mut context = PlaceholderContext::new();
        context.set_filename(&base);

        // Add captured groups
        for (idx, cap) in caps.iter().enumerate() {
            if let Some(m) = cap {
                context.set_capture(idx, m.as_str().to_string());
            }
        }

        let output_name = replace_placeholders(output_pattern, &context);
        let final_output = if no_extension {
            output_name
        } else {
            format!("{}{}", output_name, ext)
        };
        Ok(final_output)
    } else {
        Err(anyhow!("Regex did not match filename: {}", filename))
    }
}

fn apply_renames(
    work_dir: &Path,
    operations: &[RenameOperation],
    test_mode: bool,
    overwrite: bool,
    quiet: bool,
) -> Result<()> {
    // Print table if not quiet
    if !quiet {
        let mut table = Table::new();
        table.add_row(prettytable::row!["Input", "Output"]);

        for op in operations {
            table.add_row(prettytable::row![op.input, op.output]);
        }

        table.printstd();
    }

    // Apply renames unless in test mode
    if !test_mode {
        for op in operations {
            let input_path = work_dir.join(&op.input);
            let mut output_path = work_dir.join(&op.output);

            // Check if output file already exists and handle accordingly
            if output_path.exists() && !overwrite {
                // Prepend underscore
                let file_name = output_path.file_name().unwrap().to_string_lossy();
                let new_name = format!("_{}", file_name);
                output_path = output_path.parent().unwrap().join(new_name);
            }

            // Create parent directories if needed
            if let Some(parent) = output_path.parent() {
                fs::create_dir_all(parent)
                    .map_err(|e| anyhow!("Failed to create directories: {}", e))?;
            }

            fs::rename(&input_path, &output_path).map_err(|e| {
                eprintln!("[error] unable to rename '{}': {}", op.output, e);
                anyhow!("Rename failed: {}", e)
            }).ok();
        }
    }

    Ok(())
}
