          Print help (see a summary with '-h')

  -k, --mkdir
          Recursively creates all parent directories of '<OUTPUT>' if they are missing

  -m, --map <PATH>
          Sets the path of map file to be used for renaming files

          [aliases: --from-file]

      --max-depth <DEPTH>
          Optional value to set the maximum of subdirectory depth value in 'regex' mode

  -q, --quiet
          Does not print the map table to stdout

  -r, --regex <PATTERN>
          Regex pattern to match by filenames

  -s, --sort <ORDER>
          Sets the order of natural sorting (by name) to rename files using enumerator

          Possible values:
          - asc:  Sort in ascending order
          - desc: Sort in descending order

  -t, --test
          Runs in test mode without renaming actual files

          [aliases: --dry-run]

  -V, --version
          Print version

  -w, --overwrite
          Overwrites output files, otherwise, a '_' is prepended to filename

OUTPUT pattern accepts placeholders that have the format of '{{G:P}}' where 'G' is the captured group and 'P' is the padding of digits with `0`. Please refer to https://github.com/yaa110/nomino for more information.", program);
}

struct RenameOperation {
    input: String,
    output: String,
}

fn get_files(dir: &Path) -> Result<Vec<PathBuf>, String> {
    let mut files = Vec::new();
    for entry in fs::read_dir(dir)
        .map_err(|e| format!("Failed to read directory: {}", e))?
    {
        let entry = entry.map_err(|e| format!("Error reading directory entry: {}", e))?;
        let path = entry.path();
        if path.is_file() {
            files.push(path);
        }
    }
    Ok(files)
}

fn split_filename(filename: &str) -> (String, String) {
    if let Some(pos) = filename.rfind('.') {
        if pos > 0 {
            let base = filename[..pos].to_string();
            let ext = filename[pos..].to_string();
            return (base, ext);
        }
    }
    (filename.to_string(), String::new())
}

struct PlaceholderContext {
    captures: HashMap<String, String>,
}

impl PlaceholderContext {
    fn new() -> Self {
        Self {
            captures: HashMap::new(),
        }
    }

    fn set_filename(&mut self, name: &str) {
        self.captures.insert("0".to_string(), name.to_string());
    }

    fn set_capture(&mut self, idx: usize, value: String) {
        self.captures.insert(idx.to_string(), value);
    }

    fn set_auto_index(&mut self, idx: usize, value: String) {
        self.captures.insert(idx.to_string(), value);
    }

    fn get(&self, key: &str) -> Option<String> {
        self.captures.get(key).cloned()
    }
}

fn replace_placeholders(pattern: &str, ctx: &PlaceholderContext) -> String {
    let mut result = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    let mut auto_index = 1;

    while i < chars.len() {
        if chars[i] == '{' {
            let mut placeholder = String::new();
            let mut j = i + 1;
            let mut found_close = false;

            while j < chars.len() {
                if chars[j] == '}' {
                    found_close = true;
                    break;
                }
                placeholder.push(chars[j]);
                j += 1;
            }

            if found_close {
                let parts: Vec<&str> = placeholder.split(':').collect();
                let group_str = parts[0].trim();
                let padding = if parts.len() > 1 {
                    parts[1].trim().parse::<usize>().unwrap_or(0)
                } else {
                    0
                };

                let value = if group_str.is_empty() {
                    // Auto increment
                    let val = ctx.get(&auto_index.to_string()).unwrap_or_default();
                    auto_index += 1;
                    val
                } else {
                    ctx.get(group_str).unwrap_or_default()
                };

                let formatted = format_value(&value, padding);
                result.push_str(&formatted);
                i = j + 1;
            } else {
                result.push('{');
                i += 1;
            }
        } else if chars[i] == '\\' && i + 1 < chars.len() && (chars[i + 1] == '{' || chars[i + 1] == '}') {
            result.push(chars[i + 1]);
            i += 2;
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }

    result
}

fn format_value(value: &str, padding: usize) -> String {
    if padding == 0 {
        return value.to_string();
    }

    // Try to parse as number
    if let Ok(num) = value.parse::<i64>() {
        if num >= 0 {
            format!("{:0width$}", num, width = padding)
        } else {
            value.to_string()
        }
    } else {
        value.to_string()
    }
}

// Simple regex matching - only handles basic patterns
fn simple_regex_match(pattern: &str, text: &str) -> Option<Vec<String>> {
    // This is a very simplified regex implementation
    // We'll handle basic patterns like (group)

    // First, convert the pattern to a simple form
    let parts = extract_groups(pattern);

    if parts.is_empty() {
        return None;
    }

    match_pattern(&parts, text)
}

fn extract_groups(pattern: &str) -> Vec<PatternPart> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '(' {
            if !current.is_empty() {
                parts.push(PatternPart::Literal(current.clone()));
                current.clear();
            }

            let mut group = String::new();
            i += 1;
            let mut depth = 1;
            while i < chars.len() && depth > 0 {
                if chars[i] == '(' {
                    depth += 1;
                } else if chars[i] == ')' {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                group.push(chars[i]);
                i += 1;
            }
            parts.push(PatternPart::Group(group));
            i += 1;
        } else if chars[i] == '\\' && i + 1 < chars.len() {
            current.push(chars[i]);
            current.push(chars[i + 1]);
            i += 2;
        } else {
            current.push(chars[i]);
            i += 1;
        }
    }

    if !current.is_empty() {
        parts.push(PatternPart::Literal(current));
    }

    parts
}

enum PatternPart {
    Literal(String),
    Group(String),
}

fn match_pattern(parts: &[PatternPart], text: &str) -> Option<Vec<String>> {
    let mut captures = vec![text.to_string()]; // Full match at index 0
    let mut pos = 0;

    for part in parts {
        match part {
            PatternPart::Literal(lit) => {
                // Handle escape sequences
                let lit_str = lit.replace("\\d", "[0-9]")
                    .replace("\\w", "[a-zA-Z0-9_]")
                    .replace("\\s", " ");

                // Simple literal matching
                if lit_str.contains("[0-9]") {
                    // digit pattern
                    let mut end = pos;
                    while end < text.len() && text.chars().nth(end).map_or(false, |c| c.is_numeric()) {
                        end += 1;
                    }
                    if end == pos {
                        return None;
                    }
                    pos = end;
                } else if lit_str.contains("[a-zA-Z0-9_]") {
                    // word pattern
                    let mut end = pos;
                    while end < text.len() {
                        let c = text.chars().nth(end).unwrap_or('\0');
                        if c.is_alphanumeric() || c == '_' {
                            end += 1;
                        } else {
                            break;
                        }
                    }
                    if end == pos {
                        return None;
                    }
                    pos = end;
                } else {
                    // Direct literal match
                    for ch in lit_str.chars() {
                        if pos >= text.len() || text.chars().nth(pos).unwrap_or('\0') != ch {
                            return None;
                        }
                        pos += 1;
                    }
                }
            }
            PatternPart::Group(group_pattern) => {
                // Handle group pattern
                let group_str = group_pattern.replace("\\d", "[0-9]")
                    .replace("\\w", "[a-zA-Z0-9_]")
                    .replace("\\s", " ");

                if group_str.contains("[0-9]") {
                    // digit group
                    let start = pos;
                    while pos < text.len() && text.chars().nth(pos).map_or(false, |c| c.is_numeric()) {
                        pos += 1;
                    }
                    if pos == start {
                        return None;
                    }
                    captures.push(text[start..pos].to_string());
                } else if group_str.contains("[a-zA-Z0-9_]") {
                    // word group
                    let start = pos;
                    while pos < text.len() {
                        let c = text.chars().nth(pos).unwrap_or('\0');
                        if c.is_alphanumeric() || c == '_' {
                            pos += 1;
                        } else {
                            break;
                        }
                    }
                    if pos == start {
                        return None;
                    }
                    captures.push(text[start..pos].to_string());
                } else if group_str == "." {
                    // any character (but not implemented here, just match anything up to next pattern)
                    if pos < text.len() {
                        captures.push(text.chars().nth(pos).unwrap().to_string());
                        pos += 1;
                    } else {
                        return None;
                    }
                } else {
                    // Literal group match
                    let start = pos;
                    for ch in group_str.chars() {
                        if pos >= text.len() || text.chars().nth(pos).unwrap_or('\0') != ch {
                            return None;
                        }
                        pos += 1;
                    }
                    captures.push(text[start..pos].to_string());
                }
            }
        }
    }

    Some(captures)
}

fn apply_regex_replacement(
    filename: &str,
    captures: &[String],
    output_pattern: &str,
    no_extension: bool,
) -> Result<String, String> {
    let (base, ext) = if no_extension {
        (filename.to_string(), String::new())
    } else {
        split_filename(filename)
    };

    let mut context = PlaceholderContext::new();
    context.set_filename(&base);

    // Add captured groups
    for (idx, cap) in captures.iter().enumerate() {
        context.set_capture(idx, cap.clone());
    }

    let output_name = replace_placeholders(output_pattern, &context);
    let final_output = if no_extension {
        output_name
    } else {
        format!("{}{}", output_name, ext)
    };
    Ok(final_output)
}

fn apply_renames(
    work_dir: &Path,
    operations: &[RenameOperation],
    test_mode: bool,
    overwrite: bool,
    quiet: bool,
) -> Result<(), String> {
    // Print table if not quiet
    if !quiet {
        print_table(operations);
    }

    // Apply renames unless in test mode
    if !test_mode {
        for op in operations {
            let input_path = work_dir.join(&op.input);
            let mut output_path = work_dir.join(&op.output);

            // Check if output file already exists and handle accordingly
            if output_path.exists() && !overwrite {
                // Prepend underscore
                let file_name = output_path.file_name().unwrap().to_string_lossy().to_string();
                let new_name = format!("_{}", file_name);
                output_path = output_path.parent().unwrap().to_path_buf().join(new_name);
            }

            // Create parent directories if needed
            if let Some(parent) = output_path.parent() {
                fs::create_dir_all(parent)
                    .map_err(|e| format!("Failed to create directories: {}", e))?;
            }

            if let Err(e) = fs::rename(&input_path, &output_path) {
                eprintln!("[error] unable to rename '{}': {}", op.output, e);
            }
        }
    }

    Ok(())
}

fn print_table(operations: &[RenameOperation]) {
    if operations.is_empty() {
        return;
    }

    // Calculate column widths
    let mut input_width = "Input".len();
    let mut output_width = "Output".len();

    for op in operations {
        input_width = input_width.max(op.input.len());
        output_width = output_width.max(op.output.len());
    }

    // Print header
    println!("+{}+{}+", "-".repeat(input_width + 2), "-".repeat(output_width + 2));
    println!("| {:width1$} | {:width2$} |", "Input", "Output", width1 = input_width, width2 = output_width);
    println!("+{}+{}+", "-".repeat(input_width + 2), "-".repeat(output_width + 2));

    // Print rows
    for op in operations {
        println!("| {:width1$} | {:width2$} |", op.input, op.output, width1 = input_width, width2 = output_width);
    }

    println!("+{}+{}+", "-".repeat(input_width + 2), "-".repeat(output_width + 2));
}

fn parse_json_map(content: &str) -> Result<Vec<RenameOperation>, String> {
    let mut operations = Vec::new();

    // Very simple JSON parser for map files
    let trimmed = content.trim();
    if !trimmed.starts_with('{') || !trimmed.ends_with('}') {
        return Err("Invalid JSON format".to_string());
    }

    let inner = &trimmed[1..trimmed.len()-1];
    let parts = split_json_pairs(inner);

    for part in parts {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }

        // Parse "key": "value"
        if let Some(colon_pos) = part.find(':') {
            let key_part = part[..colon_pos].trim();
            let value_part = part[colon_pos+1..].trim();

            let key = parse_json_string(key_part)?;
            let value = parse_json_string(value_part)?;

            operations.push(RenameOperation {
                input: key,
                output: value,
            });
        }
    }

    Ok(operations)
}

fn split_json_pairs(s: &str) -> Vec<&str> {
    let mut pairs = Vec::new();
    let mut current_start = 0;
    let mut in_string = false;
    let mut escape = false;
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if escape {
            escape = false;
        } else if chars[i] == '\\' {
            escape = true;
        } else if chars[i] == '"' {
            in_string = !in_string;
        } else if !in_string && chars[i] == ',' {
            pairs.push(&s[current_start..i]);
            current_start = i + 1;
        }
        i += 1;
    }

    if current_start < s.len() {
        pairs.push(&s[current_start..]);
    }

    pairs
}

fn parse_json_string(s: &str) -> Result<String, String> {
    let trimmed = s.trim();
    if trimmed.starts_with('"') && trimmed.ends_with('"') {
        let content = &trimmed[1..trimmed.len()-1];
        Ok(content.replace("\\\"", "\"")
            .replace("\\\\", "\\")
            .replace("\\n", "\n")
            .replace("\\r", "\r")
            .replace("\\t", "\t"))
    } else {
        Err(format!("Invalid JSON string: {}", trimmed))
    }
}

fn generate_json_map(operations: &[RenameOperation]) -> String {
    let mut result = String::from("{\n");
    for (idx, op) in operations.iter().enumerate() {
        result.push_str("  \"");
        result.push_str(&escape_json_string(&op.output));
        result.push_str("\": \"");
        result.push_str(&escape_json_string(&op.input));
        result.push_str("\"");
        if idx < operations.len() - 1 {
            result.push(',');
        }
        result.push('\n');
    }
    result.push('}');
    result
}

fn escape_json_string(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

fn alphanumeric_sort(a: &str, b: &str) -> std::cmp::Ordering {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();

    let mut a_pos = 0;
    let mut b_pos = 0;

    loop {
        if a_pos >= a_chars.len() && b_pos >= b_chars.len() {
            return std::cmp::Ordering::Equal;
        }
        if a_pos >= a_chars.len() {
            return std::cmp::Ordering::Less;
        }
        if b_pos >= b_chars.len() {
            return std::cmp::Ordering::Greater;
        }

        let a_char = a_chars[a_pos];
        let b_char = b_chars[b_pos];

        if a_char.is_numeric() && b_char.is_numeric() {
            // Extract numbers
            let mut a_num = String::new();
            while a_pos < a_chars.len() && a_chars[a_pos].is_numeric() {
                a_num.push(a_chars[a_pos]);
                a_pos += 1;
            }

            let mut b_num = String::new();
            while b_pos < b_chars.len() && b_chars[b_pos].is_numeric() {
                b_num.push(b_chars[b_pos]);
                b_pos += 1;
            }

            let a_int = a_num.parse::<u64>().unwrap_or(0);
            let b_int = b_num.parse::<u64>().unwrap_or(0);

            match a_int.cmp(&b_int) {
                std::cmp::Ordering::Equal => continue,
                other => return other,
            }
        } else {
            match a_char.cmp(&b_char) {
                std::cmp::Ordering::Equal => {
                    a_pos += 1;
                    b_pos += 1;
                }
                other => return other,
            }
        }
    }
}
