}

fn parse_args(args: &[String]) -> Result<ParsedArgs, String> {
    let mut parsed = ParsedArgs {
        patterns: Vec::new(),
        dir: None,
        depth: None,
        no_extension: false,
        generate: None,
        mkdir: false,
        map: None,
        max_depth: None,
        quiet: false,
        regex: None,
        sort: None,
        test: false,
        overwrite: false,
    };

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help(&args[0]);
                process::exit(0);
            }
            "-V" | "--version" => {
                println!("nomino 1.6.4");
